import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CZrxoOIU.js";const f=JSON.parse('{"title":"Frequently Asked Questions","description":"","frontmatter":{},"headers":[],"relativePath":"en/old/qa.md","filePath":"en/old/qa.md","lastUpdated":1719119907000}'),o={name:"en/old/qa.md"};function i(s,e,c,d,h,l){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h1><h2 id="why-do-declared-http-interfaces-need-to-inherit-the-ihttpapi-interface" tabindex="-1">Why do declared HTTP interfaces need to inherit the IHttpApi interface? <a class="header-anchor" href="#why-do-declared-http-interfaces-need-to-inherit-the-ihttpapi-interface" aria-label="Permalink to &quot;Why do declared HTTP interfaces need to inherit the IHttpApi interface?&quot;">​</a></h2><p>One reason is to facilitate the generation of proxy classes for the interfaces by the WebApiClient library, serving as a marker. Another reason is that by inheriting the <code>IHttpApi</code> interface, the proxy classes for the HTTP interfaces have a Dispose method.</p><h2 id="can-an-http-interface-inherit-from-another-http-interface" tabindex="-1">Can an HTTP interface inherit from another HTTP interface? <a class="header-anchor" href="#can-an-http-interface-inherit-from-another-http-interface" aria-label="Permalink to &quot;Can an HTTP interface inherit from another HTTP interface?&quot;">​</a></h2><p>Yes, it is possible to inherit from another HTTP interface. The methods of the parent interface will also be treated as API methods. However, it is important to note that the interface-level attributes of the parent interface will be overridden by those of the child interface. Therefore, for better understanding, it is recommended not to use this kind of inheritance.</p><h2 id="how-can-i-validate-the-validity-of-a-proxy-before-using-the-proxyattribute-host-port-attribute" tabindex="-1">How can I validate the validity of a proxy before using the <code>[ProxyAttribute(host,port)]</code> attribute? <a class="header-anchor" href="#how-can-i-validate-the-validity-of-a-proxy-before-using-the-proxyattribute-host-port-attribute" aria-label="Permalink to &quot;How can I validate the validity of a proxy before using the `[ProxyAttribute(host,port)]` attribute?&quot;">​</a></h2><p>You can use the Validate method of the ProxyValidator object to validate the validity of a proxy.</p><h2 id="why-is-it-not-supported-to-declare-the-return-type-of-an-interface-method-as-task-instead-of-task-or-itask" tabindex="-1">Why is it not supported to declare the return type of an interface method as <code>Task</code> instead of <code>Task&lt;&gt;</code> or <code>ITask&lt;&gt;</code>? <a class="header-anchor" href="#why-is-it-not-supported-to-declare-the-return-type-of-an-interface-method-as-task-instead-of-task-or-itask" aria-label="Permalink to &quot;Why is it not supported to declare the return type of an interface method as `Task` instead of `Task&lt;&gt;` or `ITask&lt;&gt;`?&quot;">​</a></h2><p>This is a design principle. Regardless of whether the developer is interested in the return value or not, an HTTP request will either have a response or throw an exception. If you are not interested in parsing the response, you can declare the return type as <code>Task&lt;HttpResponseMessage&gt;</code> without actually parsing the <code>HttpResponseMessage</code>.</p><h2 id="how-can-i-download-a-file-using-webapiclient" tabindex="-1">How can I download a file using WebApiClient? <a class="header-anchor" href="#how-can-i-download-a-file-using-webapiclient" aria-label="Permalink to &quot;How can I download a file using WebApiClient?&quot;">​</a></h2><p>You should declare the return type of the interface as <code>ITask&lt;HttpResponseFile&gt;</code>.</p><h2 id="besides-declaring-the-return-type-of-an-interface-as-itask-httpresponsemessage-what-other-abstract-return-types-can-be-declared" tabindex="-1">Besides declaring the return type of an interface as <code>ITask&lt;HttpResponseMessage&gt;</code>, what other abstract return types can be declared? <a class="header-anchor" href="#besides-declaring-the-return-type-of-an-interface-as-itask-httpresponsemessage-what-other-abstract-return-types-can-be-declared" aria-label="Permalink to &quot;Besides declaring the return type of an interface as `ITask&lt;HttpResponseMessage&gt;`, what other abstract return types can be declared?&quot;">​</a></h2><p>Other abstract return types that can be declared include <code>ITask&lt;string&gt;</code>, <code>ITask&lt;Stream&gt;</code>, and <code>ITask&lt;Byte[]&gt;</code>.</p><h2 id="can-the-parameters-declared-in-an-interface-be-of-type-object-or-certain-base-classes" tabindex="-1">Can the parameters declared in an interface be of type Object or certain base classes? <a class="header-anchor" href="#can-the-parameters-declared-in-an-interface-be-of-type-object-or-certain-base-classes" aria-label="Permalink to &quot;Can the parameters declared in an interface be of type Object or certain base classes?&quot;">​</a></h2><p>Yes, you can declare parameters in an interface as Object or certain base classes. However, there may be issues with XML serialization for the data. In general, it is recommended to declare the parameters according to the specific types expected by the server.</p><h2 id="how-can-i-use-synchronous-requests-with-webapiclient" tabindex="-1">How can I use synchronous requests with WebApiClient? <a class="header-anchor" href="#how-can-i-use-synchronous-requests-with-webapiclient" aria-label="Permalink to &quot;How can I use synchronous requests with WebApiClient?&quot;">​</a></h2><p>WebApiClient is a wrapper for HttpClient. Since HttpClient does not provide synchronous request methods, WebApiClient also does not support synchronous requests. Incorrectly blocking ITask and Task return values can easily lead to deadlocks in certain environments.</p>',17)])])}const u=t(o,[["render",i]]);export{f as __pageData,u as default};
